PRAGMA foreign_keys = ON;
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, category_id TEXT NOT NULL REFERENCES categories(id), description TEXT NOT NULL, material TEXT NOT NULL, finish TEXT NOT NULL, length REAL NOT NULL, width REAL NOT NULL, height REAL NOT NULL, price INTEGER, status TEXT NOT NULL DEFAULT 'concept', images TEXT NOT NULL, colors TEXT NOT NULL, materials TEXT NOT NULL, model TEXT, internal_cost INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quotes (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, product_id TEXT NOT NULL, product_snapshot TEXT NOT NULL, configuration TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, area TEXT NOT NULL, consent INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'New', internal_cost INTEGER NOT NULL DEFAULT 0, final_price INTEGER, email_status TEXT NOT NULL DEFAULT 'pending', email_attempts INTEGER NOT NULL DEFAULT 0, email_updated_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE price_audit (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, old_price INTEGER, new_price INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK (id=1), minimum_margin REAL NOT NULL DEFAULT 20);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX quote_created ON quotes(created_at);
CREATE INDEX product_category ON products(category_id);
